// JS 里手写 Church 编码的布尔
const TRUE = t => f => t;
const FALSE = t => f => f;
const IF = c => t => f => c(t)(f);
IF(TRUE)("yes")("no")

// 再看「和类型」怎么用函数编码
const pair = a => b => f => f(a)(b);
const fst = p => p(TRUE);
const snd = p => p(FALSE);
snd(pair(1)(2))

// 只用 fold 实现 map / filter / length
const fold = xs => init => f => xs.reduce(f, init);
const map = xs => g => fold(xs)([])((acc, x) => [...acc, g(x)]);
const filter = xs => p => fold(xs)([])((acc, x) => p(x) ? [...acc, x] : acc);
map([1,2,3])(x => x*2)
filter([1,2,3,4])(x => x%2===0)

// 一个违反传递性的比较器：石头剪刀布
const rps = (a,b) => a===b?0 : (a==='rock'&&b==='scissors')||(a==='scissors'&&b==='paper')||(a==='paper'&&b==='rock') ? -1 : 1;
['rock','paper','scissors'].sort(rps)
['paper','scissors','rock'].sort(rps)
