// 用简单的方式模拟「效果是值」
const ReadFile = path => ({ tag: 'ReadFile', path });
const Pure = v => ({ tag: 'Pure', v });
const Bind = (m, f) => ({ tag: 'Bind', m, f });

// 解释器（换它 = 换 mock）
const runIO = prog => {
  const go = p => {
    if (p.tag === 'Pure') return p.v;
    if (p.tag === 'ReadFile') return `[file:${p.path}]`;
    if (p.tag === 'Bind') return go(p.f(go(p.m)));
  };
  return go(prog);
};
runIO(Bind(ReadFile('a.txt'), c => Pure('got ' + c)))

// 检查 Promise 是否满足结合律（它是单子，但 then 有微妙的时序）
const m = Promise.resolve(1);
const f = x => Promise.resolve(x + 1);
const g = x => Promise.resolve(x * 2);

Promise.all([
  m.then(f).then(g),
  m.then(x => f(x).then(g))
]).then(([a,b]) => `${a} === ${b} ? ${a===b}`)

// 正交：可以自由组合
const withCache = f => (...a) => f(...a);
const withLog = f => (...a) => { console.log(a); return f(...a); };
// 非正交：行为取决于组合顺序
const withRetry = (f, n) => (...a) => { for(let i=0;i<n;i++) try { return f(...a) } catch(e){ if(i===n-1) throw e } };
